// Engine profiles for the Edge Functions: validate, compile onto a story, list presets.
//
// A profile is a user's own LOOK and FLOW defaults (theme, canvas, palette, pacing). It has no
// field for data, scale, sources, notes, labels that make a claim, the renderer or any check, so
// none of those can be changed by a profile. The compile step writes only to an allowlist of look
// paths, and assertLookOnly diffs the result against the original so a bug cannot widen that.
//
// The rules (PROFILE_SCHEMA), theme defaults and presets are in profile_data.ts, GENERATED by the
// Ryagram engine repo (tests/profile_checks.py --write-fixtures), so this file holds no copy of
// them. tests/engine-profile.test.mjs replays the engine's own fixtures through this file: same
// accept/refuse decisions, same colour-guard sentences, same compiled stories.
import { BAR_RACE, PRESETS, PRESET_LIST, PROFILE_SCHEMA, THEME_DEFAULTS } from "./profile_data.ts";

export const MAX_PROFILE_BYTES = 16 * 1024;
export const MAX_PROFILES_PER_USER = 20;

export class ProfileError extends Error {
  errors: string[];
  constructor(errors: string[]) {
    super(errors.slice(0, 5).join("; "));
    this.errors = errors;
  }
}

type Json = any;

// ---------------------------------------------------------------- shape (closed JSON Schema subset)

function deepEq(a: Json, b: Json): boolean {
  if (typeof a === "boolean" || typeof b === "boolean") return a === b;
  if (Array.isArray(a) && Array.isArray(b)) return a.length === b.length && a.every((x, i) => deepEq(x, b[i]));
  return a === b;
}

function shape(node: Json, v: Json, path: string, errs: string[]): void {
  const here = path || "profile";
  if (node.enum) {
    if (!node.enum.some((a: Json) => deepEq(a, v))) {
      errs.push(`${here}: ${JSON.stringify(v)?.slice(0, 60)} is not one of ${node.enum.map((a: Json) => JSON.stringify(a)).join(", ")}`);
    }
    return;
  }
  if (node.anyOf) {
    if (!node.anyOf.some((n: Json) => { const t: string[] = []; shape(n, v, path, t); return t.length === 0; })) {
      errs.push(`${here}: matches none of the allowed forms`);
    }
    return;
  }
  switch (node.type) {
    case "object": {
      if (v === null || typeof v !== "object" || Array.isArray(v)) { errs.push(`${here}: expected an object`); return; }
      const props = node.properties ?? {};
      for (const k of Object.keys(v)) {
        if (!(k in props)) {
          errs.push(`${here}: unknown key '${k.slice(0, 40)}' (this object accepts: ${Object.keys(props).sort().join(", ")})`);
        }
      }
      for (const k of node.required ?? []) if (!(k in v)) errs.push(`${here}: missing '${k}'`);
      for (const [k, sub] of Object.entries(props)) if (k in v) shape(sub, v[k], path ? `${path}.${k}` : k, errs);
      return;
    }
    case "string": {
      if (typeof v !== "string") { errs.push(`${here}: expected a string`); return; }
      if (node.maxLength != null && v.length > node.maxLength) { errs.push(`${here}: longer than ${node.maxLength} characters`); return; }
      if (node.pattern && !new RegExp(node.pattern).test(v)) {
        errs.push(/\\u2060|\\u200b/.test(node.pattern) ? `${here}: contains control or invisible characters` : `${here}: does not match ${node.pattern}`);
      }
      return;
    }
    case "number":
    case "integer": {
      if (typeof v !== "number") { errs.push(`${here}: expected a number`); return; }
      if (!Number.isFinite(v)) { errs.push(`${here}: not a finite number`); return; }
      if (node.type === "integer" && !Number.isInteger(v)) { errs.push(`${here}: expected a whole number`); return; }
      if (v < node.minimum || v > node.maximum) errs.push(`${here}: ${v} is outside ${node.minimum}..${node.maximum}`);
      return;
    }
    case "boolean":
      if (typeof v !== "boolean") errs.push(`${here}: expected true or false`);
      return;
    default:
      errs.push(`${here}: internal: unsupported schema node`);
  }
}

export function checkShape(profile: Json): string[] {
  const errs: string[] = [];
  shape(PROFILE_SCHEMA, profile, "", errs);
  return errs;
}

// ---------------------------------------------------------------- colour guards (same sentences as the engine)

const SMALL_PATCH = 5.0;
const MIN_RAMP_SPAN = 4 * SMALL_PATCH, MIN_HIGH_VS_PAGE = 4 * SMALL_PATCH, MIN_DOTS_VS_PAGE = 4 * SMALL_PATCH;
const MIN_DOT_PAIR = 4 * SMALL_PATCH, MIN_NODATA_VS_FILL = SMALL_PATCH, MIN_MUTED_CONTRAST = 3.0;

const rgb = (h: string): number[] => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const lin = (c: number) => { c /= 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };

function lab(c: number[]): number[] {
  const [r, g, b] = c.map(lin);
  const x = (0.4124 * r + 0.3576 * g + 0.1805 * b) / 0.95047;
  const y = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  const z = (0.0193 * r + 0.1192 * g + 0.9505 * b) / 1.08883;
  const f = (t: number) => (t > 216 / 24389 ? t ** (1 / 3) : (841 / 108) * t + 4 / 29);
  const [fx, fy, fz] = [f(x), f(y), f(z)];
  return [116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)];
}
const dE = (p: string, q: string) => { const a = lab(rgb(p)), b = lab(rgb(q)); return Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0)); };
function lum(c: number[]) { const [r, g, b] = c.map(lin); return 0.2126 * r + 0.7152 * g + 0.0722 * b; }
function contrast(a: string, b: string) { const [hi, lo] = [lum(rgb(a)), lum(rgb(b))].sort((x, y) => y - x); return (hi + 0.05) / (lo + 0.05); }

export function checkColours(profile: Json): string[] {
  const look = profile.look ?? {};
  const theme = look.theme ?? "dark";
  const eff = (section: string, key: string, ...path: string[]): string => {
    let n = look;
    for (const p of path) n = n?.[p];
    return typeof n === "string" ? n : THEME_DEFAULTS[theme][section][key];
  };
  const errs: string[] = [];
  const page = eff("page", "background", "page_background");
  const ramp = look.ramp ?? {};
  const low = eff("choropleth", "low", "ramp", "low"), high = eff("choropleth", "high", "ramp", "high");
  if (ramp.low || ramp.high) {
    const span = dE(low, high);
    if (span < MIN_RAMP_SPAN) errs.push(`look.ramp: low ${low} and high ${high} are only ${span.toFixed(0)} dE apart; they need at least ${MIN_RAMP_SPAN.toFixed(0)} so five bands can be told apart. Move them further apart in lightness.`);
    const far = dE(high, page);
    if (far < MIN_HIGH_VS_PAGE) errs.push(`look.ramp.high ${high} is only ${far.toFixed(0)} dE from the page ${page}; the highest values would dissolve into the background. Needs at least ${MIN_HIGH_VS_PAGE.toFixed(0)}.`);
  }
  if (ramp.continuous && ramp.mode === "hatch") errs.push("look.ramp: continuous colour needs mode 'solid', not 'hatch'.");
  const dots = look.dots ?? {};
  if (dots.color) {
    const d = dE(dots.color, page);
    if (d < MIN_DOTS_VS_PAGE) errs.push(`look.dots.color ${dots.color} is only ${d.toFixed(0)} dE from the page ${page}; dots would not be seen. Needs at least ${MIN_DOTS_VS_PAGE.toFixed(0)}.`);
  }
  if (dots.color || dots.baseline_color) {
    const a = eff("dots", "color", "dots", "color"), b = eff("dots", "baseline_color", "dots", "baseline_color");
    const d = dE(a, b);
    if (d < MIN_DOT_PAIR) errs.push(`look.dots: color ${a} and baseline_color ${b} are only ${d.toFixed(0)} dE apart; new dots and the stock would read as one. Needs at least ${MIN_DOT_PAIR.toFixed(0)}.`);
  }
  const st = look.state ?? {};
  if (st.fill || st.no_data_fill) {
    const fill = eff("state", "fill", "state", "fill"), nd = eff("state", "no_data_fill", "state", "no_data_fill");
    const d = dE(fill, nd);
    if (d < MIN_NODATA_VS_FILL) errs.push(`look.state: no_data_fill ${nd} is only ${d.toFixed(1)} dE from fill ${fill}; 'not published' areas would look like measured ones. Needs at least ${MIN_NODATA_VS_FILL.toFixed(0)}.`);
  }
  if (look.text_muted || look.page_background) {
    const muted = eff("text", "muted", "text_muted");
    const r = contrast(muted, page);
    if (r < MIN_MUTED_CONTRAST) errs.push(`look.text_muted ${muted} on page ${page} has contrast ${r.toFixed(1)}:1; it needs at least ${MIN_MUTED_CONTRAST}:1 to be read.`);
  }
  return errs;
}

export function parseProfile(raw: unknown): Json {
  if (typeof raw === "string") {
    if (new TextEncoder().encode(raw).length > MAX_PROFILE_BYTES) throw new ProfileError([`profile is larger than ${MAX_PROFILE_BYTES} bytes`]);
    try { return JSON.parse(raw); } catch (e) { throw new ProfileError([`profile is not valid JSON (${String((e as Error).message).slice(0, 120)})`]); }
  }
  if (new TextEncoder().encode(JSON.stringify(raw ?? null)).length > MAX_PROFILE_BYTES) throw new ProfileError([`profile is larger than ${MAX_PROFILE_BYTES} bytes`]);
  return raw;
}

/** Shape, then colours. Throws ProfileError listing EVERY problem. Returns a deep copy. */
export function validateProfile(raw: unknown): Json {
  const profile = JSON.parse(JSON.stringify(parseProfile(raw)));
  const errs = checkShape(profile);
  if (errs.length) throw new ProfileError(errs);
  const bad = checkColours(profile);
  if (bad.length) throw new ProfileError(bad);
  return profile;
}

// ---------------------------------------------------------------- compile

/** The ONLY paths a profile may change in a story. `*` is one clip index. Mirrors schema.py LOOK_PATHS. */
export const LOOK_PATHS = [
  "sequence.theme", "sequence.canvas", "sequence.fps", "sequence.hold_seconds",
  "sequence.style_overrides.page.background", "sequence.style_overrides.text.muted",
  "sequence.style_overrides.choropleth.low", "sequence.style_overrides.choropleth.high",
  "sequence.style_overrides.choropleth.mode", "sequence.style_overrides.choropleth.steps",
  "sequence.style_overrides.choropleth.continuous", "sequence.style_overrides.hatch.line_color",
  "sequence.style_overrides.dots.color", "sequence.style_overrides.dots.baseline_color",
  "sequence.style_overrides.dots.radius", "sequence.style_overrides.state.fill",
  "sequence.style_overrides.state.no_data_fill", "sequence.style_overrides.state.outline_width",
  "sequence.style_overrides.bars.swap_seconds", "sequence.style_overrides.bars.label_width",
  "sequence.style_overrides.bars.value_width",
  "sequence.clips.*.transition", "sequence.clips.*.fade", "sequence.clips.*.align",
];

function allowed(path: string): boolean {
  const parts = path.split(".");
  return LOOK_PATHS.some((pat) => {
    const want = pat.split(".");
    return parts.length >= want.length && want.every((w, i) => (w === "*" ? /^\d+$/.test(parts[i]) : w === parts[i]));
  });
}

function flatten(node: Json, prefix = "", out: Record<string, Json> = {}): Record<string, Json> {
  if (node && typeof node === "object" && !Array.isArray(node)) {
    for (const [k, v] of Object.entries(node)) flatten(v, prefix ? `${prefix}.${k}` : k, out);
    if (!Object.keys(node).length) out[prefix] = {};
  } else if (Array.isArray(node) && node.length && node.every((x) => x && typeof x === "object" && !Array.isArray(x))) {
    out[prefix + ".#len"] = node.length;
    node.forEach((x, i) => flatten(x, `${prefix}.${i}`, out));
  } else {
    out[prefix] = node;
  }
  return out;
}

export function assertLookOnly(before: Json, after: Json): string[] {
  const a = flatten(before), b = flatten(after);
  const changed: string[] = [], bad: string[] = [];
  for (const p of [...new Set([...Object.keys(a), ...Object.keys(b)])].sort()) {
    if (!(p in a) || !(p in b) || JSON.stringify(a[p]) !== JSON.stringify(b[p])) {
      changed.push(p);
      if (!allowed(p)) bad.push(p);
    }
  }
  if (bad.length) throw new ProfileError(bad.map((p) => `the compiled story differs from the original outside the look fields, at '${p}'; a profile may not change that`));
  return changed;
}

function put(story: Json, path: string, value: Json, fill: boolean): void {
  if (!allowed(path)) throw new ProfileError([`internal: '${path}' is not a look path`]);
  const parts = path.split(".");
  let node = story;
  for (const p of parts.slice(0, -1)) {
    if (node[p] === undefined || node[p] === null || typeof node[p] !== "object") node[p] = {};
    node = node[p];
  }
  const last = parts[parts.length - 1];
  if (fill && last in node) return;
  node[last] = JSON.parse(JSON.stringify(value));
}

export type Report = { changed: string[]; not_applied: string[]; warnings: string[] };

/** A NEW story with the profile's look applied, and a report. The argument is untouched. */
export function applyProfile(rawProfile: unknown, story: Json, mode: "restyle" | "fill" = "restyle"): { story: Json; report: Report } {
  if (mode !== "restyle" && mode !== "fill") throw new ProfileError([`mode must be 'restyle' or 'fill', not '${mode}'`]);
  const prof = validateProfile(rawProfile);
  const fill = mode === "fill";
  const out = JSON.parse(JSON.stringify(story));
  const clips = out?.sequence?.clips;
  if (!Array.isArray(clips)) throw new ProfileError(["the story has no sequence.clips to apply a look to"]);
  const look = prof.look ?? {}, pace = prof.pacing ?? {};
  const warnings: string[] = [];
  const set = (path: string, v: Json) => put(out, path, v, fill);

  for (const k of ["theme", "canvas", "fps"]) if (k in look) set(`sequence.${k}`, look[k]);
  if ("page_background" in look) set("sequence.style_overrides.page.background", look.page_background);
  if ("text_muted" in look) set("sequence.style_overrides.text.muted", look.text_muted);
  for (const [k, v] of Object.entries(look.ramp ?? {})) set(`sequence.style_overrides.choropleth.${k}`, v);
  if ("hatch_line_color" in look) set("sequence.style_overrides.hatch.line_color", look.hatch_line_color);
  for (const [k, v] of Object.entries(look.dots ?? {})) set(`sequence.style_overrides.dots.${k}`, v);
  for (const [k, v] of Object.entries(look.state ?? {})) set(`sequence.style_overrides.state.${k}`, v);
  for (const [k, v] of Object.entries(look.bars ?? {})) set(`sequence.style_overrides.bars.${k}`, v);
  if ("hold_seconds" in pace) set("sequence.hold_seconds", pace.hold_seconds);
  clips.forEach((clip: Json, i: number) => {
    if ("transition" in pace && i > 0) set(`sequence.clips.${i}.transition`, pace.transition);
    if (clip.kind === "title") for (const k of ["fade", "align"]) if (k in (pace.title_card ?? {})) set(`sequence.clips.${i}.${k}`, pace.title_card[k]);
  });

  // A house hold time below a bar race's own default can break the bar-race checks.
  if (pace.hold_seconds && !(fill && story?.sequence?.hold_seconds)) {
    const shown = clips.filter((c: Json) => c.kind === "render" && BAR_RACE.views.includes(c.view) && !c.hold_seconds);
    if (shown.length && pace.hold_seconds < BAR_RACE.hold_seconds) {
      warnings.push(`pacing.hold_seconds ${pace.hold_seconds} is below the bar race's own default of ${BAR_RACE.hold_seconds} s per period; rows may not be able to cross that fast and the bar-race checks may fail. Make a contact sheet first.`);
    }
  }
  // A portrait canvas is accepted by the worker, but the engine has no vertical layout yet.
  const cv = out.sequence.canvas;
  if (Array.isArray(cv) && cv[1] > cv[0]) {
    warnings.push("this canvas is vertical, but the engine has no vertical layout yet: the 16:9 drawing is fitted into the frame with bars above and below, not re-laid-out (DESIGN-VERTICAL.md is a spec, not built). The contact sheet shows the drawing, not the fitted frame.");
  }
  const pinned = story?.sequence?.style_overrides?.choropleth?.mode;
  const want = look.ramp?.mode;
  if (pinned && want && pinned !== want && !fill) {
    warnings.push(`this film's template pins choropleth mode '${pinned}'; the profile changes it to '${want}'. Make a contact sheet before rendering: small areas (counties) cannot carry hatching.`);
  }
  const co = out.sequence.style_overrides?.choropleth;
  if (co?.continuous && co?.mode === "hatch") throw new ProfileError(["the result asks for continuous colour with hatching; continuous needs mode 'solid'"]);

  const changed = assertLookOnly(story, out);
  const reserved = prof.reserved ?? {};
  const not_applied = Object.entries(reserved).flatMap(([sec, d]) => Object.keys(d as object).map((k) => `reserved.${sec}.${k}`));
  return { story: out, report: { changed, not_applied, warnings } };
}

// ---------------------------------------------------------------- presets

export const listPresets = () => PRESET_LIST.map((p) => ({ ...p }));

export function getPreset(id: string): Json {
  if (!/^[a-z0-9][a-z0-9-]{0,39}$/.test(id) || !(id in PRESETS)) {
    throw new ProfileError([`no preset named '${id}'; have ${PRESET_LIST.map((p) => p.id).join(", ")}`]);
  }
  return validateProfile(PRESETS[id]);
}

export function forkPreset(id: string, name: string, title?: string): Json {
  const p = getPreset(id);
  p.name = name;
  p.based_on = id;
  if (title) p.title = title;
  return validateProfile(p);
}

export const profileSchema = () => JSON.parse(JSON.stringify(PROFILE_SCHEMA));
